CREATE CACHED TABLE "public"."eventos"(
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 65) DEFAULT ON NULL NOT NULL,
    "categoria" CHARACTER VARYING(100),
    "descripcion" CHARACTER VARYING,
    "direccion" CHARACTER VARYING(300),
    "expositores_principales" CHARACTER VARYING(500),
    "fecha_hora" TIMESTAMP(6) NOT NULL,
    "nombre" CHARACTER VARYING(200) NOT NULL,
    "organizadores" CHARACTER VARYING(300),
    "tiene_alojamiento" BOOLEAN NOT NULL,
    "tiene_comidas" BOOLEAN NOT NULL,
    "tiene_estacionamiento" BOOLEAN NOT NULL,
    "tiene_locomocion" BOOLEAN NOT NULL
);
ALTER TABLE "public"."eventos" ADD CONSTRAINT "public"."CONSTRAINT_A" PRIMARY KEY("id");
